pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        value = bound(value, 0, address(c).balance);
        vm.assume(target != address(0));
        uint256 depositsBefore = c.depositsCount();
        uint256 balanceBefore = address(c).balance;
        (bool success,) = address(c).call{value: value}("");
        if (success) {
            // receive() increments depositsCount by at most 1 per wei received
            uint256 depositsAfterReceive = c.depositsCount();
            assertTrue(depositsAfterReceive <= depositsBefore + value);
        }
        uint256 depositsBeforeSend = c.depositsCount();
        (bool sendSuccess,) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));
        if (sendSuccess) {
            // sendMoney does not directly change depositsCount, but callbacks via receive could
            // After sendMoney, depositsCount should not have increased by more than balance decrease
            uint256 depositsAfterSend = c.depositsCount();
            uint256 balanceAfter = address(c).balance;
            // If ETH left the contract, the difference must be accounted by receive triggering
            // but receive only increases by at most 1 per wei, so max increase is (balanceBefore - balanceAfter)
            assertTrue(depositsAfterSend <= depositsBeforeSend + (balanceBefore - balanceAfter));
        }
    }
}

