import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data, uint256 numReceives) public {
        vm.assume(numReceives <= 100);
        // First, perform numReceives calls to receive to increase depositsCount
        for (uint256 i = 0; i < numReceives; i++) {
            (bool success, ) = address(c).call{value: 0}("");
            vm.assume(success);
        }
        uint256 countBefore = c.depositsCount();
        // ensure owner can call sendMoney
        vm.prank(c.owner());
        (bool sendSuccess, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        uint256 countAfter = c.depositsCount();
        // The rule: if sendMoney did not revert, depositsCount remains unchanged because sendMoney does not affect depositsCount
        // However, the mutant decrements depositsCount in receive, but here we are testing sendMoney, not receive.
        // Actually, the key is: sendMoney does not call receive, so depositsCount should stay the same.
        assertTrue(countAfter == countBefore || sendSuccess == false);
    }
}

